import rules_lib

def check(ctx):
    listed_raw = ctx['SubjectProperty.listed_for_sale_last_6_months']
    listed = rules_lib.flag(listed_raw)
    missing = rules_lib.gaps(listed=listed)
    if missing:
        return rules_lib.unknown(*missing)
    if not listed:
        return True

    occupancy_subtype = ctx['SubjectProperty.occupancy_subtype']
    missing = rules_lib.gaps(occupancy_subtype=occupancy_subtype)
    if missing:
        return rules_lib.unknown(*missing)
    investment = rules_lib.same(occupancy_subtype, 'investment')

    if investment:
        lease = rules_lib.flag(ctx['SubjectProperty.has_current_lease'])
        vacant = rules_lib.flag(ctx['SubjectProperty.is_vacant'])
    else:
        lease = None
        vacant = None

    interest_only = rules_lib.flag(ctx['MortgageLoanInformation.is_interest_only'])
    cltv = ctx['LoanCore.cltv_percent']
    cltv_within_limit = rules_lib.band(cltv, [(65, True)], above=False)

    missing = rules_lib.gaps(
        lease=lease if investment else True,
        vacant=vacant if investment else False,
        interest_only=interest_only,
        cltv_within_limit=cltv_within_limit,
    )
    if missing:
        return rules_lib.unknown(*missing)

    return (
        (not investment or (lease and not vacant))
        and not interest_only
        and cltv_within_limit
    )

import rules_lib

def check(ctx):
    property_type = ctx['SubjectProperty.property_type']
    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(property_type=property_type, cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    non_warrantable = rules_lib.same(property_type, 'Non-Warrantable Condo')
    condotel = rules_lib.same(property_type, 'Condotel / PUDtel')
    two_to_four = rules_lib.same(property_type, '2-4 Unit', '2-4 Units')
    manufactured = rules_lib.same(property_type, 'Manufactured Home', 'Manufactured')
    warrantable = rules_lib.same(property_type, 'Warrantable Condo', 'Warrantable Condos')

    limit = None
    state = None
    if non_warrantable or condotel or manufactured:
        purpose = ctx['LoanCore.loan_purpose']
        missing = rules_lib.gaps(purpose=purpose)
        if missing:
            return rules_lib.unknown(*missing)

        if rules_lib.same(purpose, 'purchase'):
            if non_warrantable:
                limit = 80
            elif condotel:
                limit = 75
            else:
                limit = 65
        elif rules_lib.same(purpose, 'refi r/t', 'refinance r/t'):
            if non_warrantable:
                limit = 75
            elif condotel:
                limit = 70
            else:
                limit = 60
        elif rules_lib.same(purpose, 'refi c/o', 'refinance c/o'):
            if non_warrantable:
                limit = 75
            elif condotel:
                limit = 65
            else:
                limit = 60
        else:
            return False

        if non_warrantable or condotel:
            state = ctx['SubjectProperty.state']
            missing = rules_lib.gaps(state=state)
            if missing:
                return rules_lib.unknown(*missing)
            if rules_lib.same(state, 'Florida', 'FL'):
                limit -= 5

    elif two_to_four:
        limit = 80

    if warrantable and cltv > 80.00:
        state = ctx['SubjectProperty.state']
        missing = rules_lib.gaps(state=state)
        if missing:
            return rules_lib.unknown(*missing)

    if limit is not None and cltv > limit:
        return False

    if cltv > 80.00:
        if rules_lib.same(property_type, 'SFR', 'Townhome', 'PUD'):
            return True
        if warrantable and not rules_lib.same(state, 'Florida', 'FL'):
            return True
        return False

    return True

import decimal
import rules_lib


def check(ctx):
    rural = ctx['SubjectProperty.is_rural']
    missing = rules_lib.gaps(rural=rural)
    if missing:
        return rules_lib.unknown(*missing)

    rural_flag = rules_lib.flag(rural)
    if rural_flag is None:
        return rules_lib.unknown('SubjectProperty.is_rural')
    if not rural_flag:
        return True

    purpose = ctx['LoanCore.loan_purpose']
    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(purpose=purpose, cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(purpose, 'purchase'):
        maximum = decimal.Decimal('80')
    elif rules_lib.same(purpose, 'refi r/t', 'refinance rate & term'):
        maximum = decimal.Decimal('75')
    elif rules_lib.same(purpose, 'refi c/o', 'refinance cash-out'):
        maximum = decimal.Decimal('70')
    else:
        return rules_lib.unknown('LoanCore.loan_purpose')

    try:
        cltv_number = decimal.Decimal(str(cltv))
    except (decimal.InvalidOperation, ValueError, TypeError):
        return rules_lib.unknown('LoanCore.cltv_percent')
    return cltv_number <= maximum

