        cltv_limit = 70
    elif rules_lib.same(
        purpose,
        'refinance rate & term', 'rate & term refinance', 'rate & term',
        'refinance rate and term', 'rate and term refinance',
        'refinance cash-out', 'cash-out refinance', 'cash-out',
